CREATE TRIGGER [Ordini_insert_trigger] ON [Ordini] FOR INSERT AS
UPDATE [side] SET [sync_row_is_tombstone] = 0, [local_update_peer_key] = 0, [restore_timestamp] = NULL, [update_scope_local_id] = NULL, [last_change_datetime] = GETDATE() FROM [Ordini_tracking] [side] JOIN INSERTED AS [i] ON [side].[Keys] = [i].[Keys]
INSERT INTO [Ordini_tracking] ([i].[Keys], [create_scope_local_id], [local_create_peer_key], [local_create_peer_timestamp], [update_scope_local_id], [local_update_peer_key], [sync_row_is_tombstone], [last_change_datetime], [restore_timestamp]) SELECT [i].[Keys], NULL, 0, @@DBTS+1, NULL, 0, 0, GETDATE() , NULL FROM INSERTED AS [i] LEFT JOIN [Ordini_tracking] [side] ON [side].[Keys] = [i].[Keys] WHERE [side].[Keys] IS NULL
